pragma solidity ^0.8.19;

import {Period} from "./IPredictionManager.sol";

struct PendingPrediction {
    address tokenIn;
    uint96 amountIn;     // tokenIn decimals
    address predictionPairBase;
    uint96 openFee;      // tokenIn decimals
    address user;
    uint64 price;        // 1e8
